mapper.sql:
WHERE customers.is_active = 3
AND customers.customer_type = 2
AND customers.id IN (SELECT customer_id FROM customer_companies WHERE company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId}))
AND customers.created_by = #{userId}

    AND (
        customers.lead_code LIKE CONCAT("%", #{filter.searchText}, "%")
        OR customers.name LIKE CONCAT("%", #{filter.searchText}, "%")
        OR customers.main_number LIKE CONCAT("%", #{filter.searchText}, "%")
    )


    AND customers.source_id = #{filter.sourceId}


    AND customers.created_by = #{filter.createdBy}


    AND customers.id IN (
        SELECT customer_id FROM customer_companies WHERE company_id = #{filter.companyId}
    )


    AND customers.id IN (
        SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.leadGroupId}
    )


    AND DATE(customers.created) >= #{filter.dateFrom}


    AND DATE(customers.created) <= #{filter.dateTo}




            AND customers.id IN (
                SELECT customer_id FROM customer_contacts
                INNER JOIN crm_activities_cards ON customer_contacts.id = crm_activities_cards.customer_contact_id
                WHERE crm_activities_cards.is_active = 1
                GROUP BY customer_contacts.customer_id
            )


            AND customers.id NOT IN (
                SELECT customer_id FROM customer_contacts
                INNER JOIN crm_activities_cards ON customer_contacts.id = crm_activities_cards.customer_contact_id
                WHERE crm_activities_cards.is_active = 1
                GROUP BY customer_contacts.customer_id
            )

mapper.select:
SELECT



GROUP BY customers.id
ORDER BY


        ${filter.orderBy}


        customers.lead_code DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM customers
WHERE is_active = 3
AND customer_type = 2
AND name = #{name}

    AND id != #{id}

mapper.update:
UPDATE customer_contacts
SET customer_id = #{lead.id}
WHERE id = #{lead.leadContactId}
AND is_active = 3
AND contact_type = 2

UPDATE customer_contacts
SET position = #{position}
WHERE id = #{leadContactId}
AND is_active = 3
AND contact_type = 2

mapper.sql:
WHERE crm_activities_cards.is_active = 1 AND customers.customer_type = 2 AND customers.is_active = 3 AND customers.id IN (SELECT customer_id FROM customer_companies WHERE company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId}))
AND customers.id = #{filter.leadId}
AND ( crm_activities_cards.issue_date LIKE CONCAT("%", #{filter.searchText}, "%") OR crm_activities_status.name LIKE CONCAT("%", #{filter.searchText}, "%") OR customer_contacts.contact_name LIKE CONCAT("%", #{filter.searchText}, "%") OR crm_activities_cards.position LIKE CONCAT("%", #{filter.searchText}, "%") OR crm_activities_cards.subject LIKE CONCAT("%", #{filter.searchText}, "%") OR crm_activities_cards.result_action LIKE CONCAT("%", #{filter.searchText}, "%") OR crm_activities_cards.other LIKE CONCAT("%", #{filter.searchText}, "%") )

mapper.select:
SELECT



GROUP BY crm_activities_cards.id
ORDER BY


        ${filter.orderBy}


        crm_activities_cards.issue_date DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, contract_name AS name, contract_url AS url, created AS created
FROM customer_contracts
WHERE customer_id = #{leadId}

SELECT id AS id, terminate_name AS name, terminate_url AS url, created AS created
FROM customer_terminates
WHERE customer_id = #{leadId}

SELECT id AS id, survey_name AS name, survey_url AS url, created AS created
FROM customer_surveys
WHERE customer_id = #{leadId}
